// 🔗 Fusion données - SOLUTION SIMPLE v7
// STRATÉGIE: Seulement input actuel + all inputs

const currentInput = $input.item;
const allInputs = $input.all();

console.log('📊 DEBUG:');
console.log('- Current input type:', typeof currentInput);
console.log('- All inputs count:', allInputs.length);
console.log('- Current JSON keys:', currentInput?.json ? Object.keys(currentInput.json) : 'null');
console.log('- Current binary keys:', currentInput?.binary ? Object.keys(currentInput.binary) : 'null');

// Parse OpenAI depuis input actuel
let aiTitle = 'Titre IA manquant';
let aiSubtitle = 'Sous-titre IA manquant';
let aiBody = 'Corps IA manquant';

if (currentInput?.json && Array.isArray(currentInput.json)) {
  const aiMessage = currentInput.json[0]?.message;
  if (aiMessage?.content) {
    const aiContent = aiMessage.content;
    console.log('🤖 AI CONTENT TROUVÉ:', aiContent.substring(0, 200));

    try {
      const cleanJson = aiContent
        .replace(/```json/g, '')
        .replace(/```/g, '')
        .trim();

      const parsed = JSON.parse(cleanJson);
      console.log('🤖 AI PARSED:', parsed);

      if (parsed.title) aiTitle = parsed.title;
      if (parsed.subtitle) aiSubtitle = parsed.subtitle;
      if (parsed.body) aiBody = parsed.body;

      console.log('✅ AI parsing SUCCESS');
    } catch (error) {
      console.log('❌ AI parsing FAILED:', error.message);
    }
  } else {
    console.log('❌ Pas de message.content dans input actuel');
  }
} else {
  console.log('❌ Input actuel pas un array');
}

// Récupération binaires depuis input actuel
const finalBinary = {};
let binaryFound = false;

console.log('📎 RECHERCHE BINAIRES:');
if (currentInput?.binary && Object.keys(currentInput.binary).length > 0) {
  Object.keys(currentInput.binary).forEach(key => {
    const binaryData = currentInput.binary[key];
    console.log(`📎 Binary [${key}]:`, {
      exists: !!binaryData,
      type: typeof binaryData,
      hasData: !!(binaryData?.data),
      hasId: !!(binaryData?.id)
    });

    if (binaryData && (binaryData.data || binaryData.id)) {
      finalBinary.images = binaryData;
      console.log(`✅ BINARY VALID: ${key} → images`);
      binaryFound = true;
    }
  });
} else {
  console.log('⚠️ Pas de binaires dans input actuel');
}

const result = {
  json: {
    contenu: 'Contenu depuis input OpenAI',
    subtitle: '',
    ai_title: aiTitle,
    ai_subtitle: aiSubtitle,
    ai_body: aiBody,
    debug: {
      current_input_found: !!currentInput,
      ai_array: Array.isArray(currentInput?.json),
      ai_message: !!(currentInput?.json?.[0]?.message?.content),
      binary_found: binaryFound,
      binary_count: Object.keys(finalBinary).length
    }
  },
  binary: finalBinary
};

console.log('🎯 RÉSULTAT:');
console.log('- AI Title:', result.json.ai_title);
console.log('- Binary count:', Object.keys(result.binary).length);

return result;

const r = $input.item.json;
const fusionData = $node["🔗 Fusion données"].json;

if (r.success) {
  return { 
    json: { 
      status: 'success', 
      project_id: r.project_id, 
      download_url: 'http://host.docker.internal:5003/api/download/' + r.project_id,
      ai_analysis: {
        title: fusionData.ai_title || 'Titre non disponible',
        subtitle: fusionData.ai_subtitle || 'Sous-titre non disponible',
        body_preview: (fusionData.ai_body || 'Corps non disponible').substring(0, 100) + '...'
      },
      debug: {
        fusion_keys: fusionData ? Object.keys(fusionData) : [],
        binary_preserved: fusionData.debug?.binary_count > 0
      }
    } 
  };
}
return { 
  json: { 
    status: 'error', 
    error: r.error || 'Erreur inconnue', 
    debug: {
      flask_response: r,
      fusion_data: fusionData
    }
  } 
};
